sealed interface Pagamento permits Pix, Cartao, Boleto {}
record Pix(String chave) implements Pagamento {}
record Cartao(String numero, int parcelas) implements Pagamento {}
record Boleto(LocalDate vencimento) implements Pagamento {}

BigDecimal taxa(Pagamento p) {
    return switch (p) {
        case Pix pix -> BigDecimal.ZERO;
        case Cartao(var numero, var parcelas) when parcelas > 1 -> new BigDecimal("0.05");
        case Cartao c -> new BigDecimal("0.03");
        case Boleto b -> new BigDecimal("2.50");
    };
}
